CREATE TABLE sites (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL) STRICT;
INSERT INTO sites VALUES ('default','Default site',unixepoch()*1000);
CREATE TABLE collectors (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL REFERENCES sites(id), name TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(site_id,name), UNIQUE(id,site_id)) STRICT;
CREATE TABLE credential_references (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL REFERENCES sites(id), name TEXT NOT NULL, kind TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(site_id,name), UNIQUE(id,site_id)) STRICT;
CREATE TABLE encrypted_secrets (credential_id TEXT PRIMARY KEY NOT NULL REFERENCES credential_references(id) ON DELETE CASCADE, key_id TEXT NOT NULL, nonce TEXT NOT NULL CHECK(length(nonce)=24), ciphertext TEXT NOT NULL, tag TEXT NOT NULL CHECK(length(tag)=32)) STRICT;
CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, username TEXT NOT NULL COLLATE NOCASE UNIQUE, password TEXT NOT NULL CHECK(password GLOB 'scrypt:*:*' AND length(password)=168), name TEXT, role TEXT NOT NULL DEFAULT 'viewer' CHECK(role IN ('admin','operator','viewer')), created_at INTEGER NOT NULL) STRICT;
CREATE TABLE sessions (token TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), company_name TEXT NOT NULL, default_subnet TEXT NOT NULL DEFAULT '', polling_interval INTEGER NOT NULL CHECK(polling_interval>=1000), auth_enabled INTEGER NOT NULL CHECK(auth_enabled IN (0,1)), webhook_url TEXT CHECK(webhook_url IS NULL OR webhook_url='')) STRICT;
INSERT INTO settings VALUES (1,'NetPulse','',2500,1,NULL);
CREATE TABLE nodes (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL DEFAULT 'default' REFERENCES sites(id), name TEXT NOT NULL, ip TEXT NOT NULL, type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'unknown', vendor TEXT, model TEXT, location TEXT, rack TEXT, os_version TEXT, snmp_version TEXT, credential_id TEXT, ports_open TEXT, last_seen INTEGER, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), UNIQUE(site_id,ip), UNIQUE(id,site_id), FOREIGN KEY(credential_id,site_id) REFERENCES credential_references(id,site_id)) STRICT;
CREATE TABLE switch_ports (id TEXT PRIMARY KEY NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, port_number INTEGER NOT NULL CHECK(port_number>0), port_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'unknown', speed_mbps INTEGER, vlan INTEGER CHECK(vlan BETWEEN 1 AND 4094), connected_device_id TEXT REFERENCES nodes(id) ON DELETE SET NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()*1000), UNIQUE(node_id,port_number), UNIQUE(id,node_id)) STRICT;
CREATE TABLE camera_channels (id TEXT PRIMARY KEY NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, channel INTEGER NOT NULL, name TEXT NOT NULL, resolution TEXT, fps INTEGER, codec TEXT, status TEXT DEFAULT 'unknown', UNIQUE(node_id,channel)) STRICT;
CREATE TABLE monitor_definitions (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL REFERENCES sites(id), node_id TEXT NOT NULL, interface_id TEXT, collector_id TEXT NOT NULL, metric_name TEXT NOT NULL CHECK(metric_name IN ('cpu','memory','disk','latency','availability','rx_bytes','tx_bytes','errors','packets','power','uptime','packet_loss')), units TEXT NOT NULL CHECK(units IN ('1','percent','ms','s','bytes','bits/s','packets','errors','watts')), semantics TEXT NOT NULL CHECK(semantics IN ('counter','gauge')), interval_ms INTEGER NOT NULL CHECK(interval_ms>=1000), created_at INTEGER NOT NULL, UNIQUE(node_id,metric_name,interface_id), FOREIGN KEY(node_id,site_id) REFERENCES nodes(id,site_id) ON DELETE CASCADE, FOREIGN KEY(interface_id,node_id) REFERENCES switch_ports(id,node_id) ON DELETE CASCADE, FOREIGN KEY(collector_id,site_id) REFERENCES collectors(id,site_id)) STRICT;
CREATE UNIQUE INDEX monitor_device_identity ON monitor_definitions(node_id,metric_name) WHERE interface_id IS NULL;
CREATE TABLE measurements (id TEXT PRIMARY KEY NOT NULL, monitor_id TEXT NOT NULL REFERENCES monitor_definitions(id) ON DELETE CASCADE, observed_at INTEGER NOT NULL CHECK(observed_at>=0), received_at INTEGER NOT NULL CHECK(received_at>=0), quality TEXT NOT NULL CHECK(quality IN ('good','stale','error','unknown')), source TEXT NOT NULL CHECK(source IN ('icmp','snmp','agent','manual')), value REAL, counter_value TEXT CHECK(counter_value IS NULL OR (length(counter_value) BETWEEN 1 AND 20 AND counter_value NOT GLOB '*[^0-9]*' AND (length(counter_value)<20 OR counter_value<='18446744073709551615'))), CHECK((quality='good' AND ((value IS NULL)!=(counter_value IS NULL))) OR (quality!='good' AND value IS NULL AND counter_value IS NULL))) STRICT;
CREATE INDEX measurements_history ON measurements(monitor_id,observed_at DESC);
CREATE INDEX measurements_retention ON measurements(observed_at);
CREATE TRIGGER measurement_semantics BEFORE INSERT ON measurements WHEN NEW.quality='good' BEGIN SELECT CASE WHEN ((SELECT semantics FROM monitor_definitions WHERE id=NEW.monitor_id)='counter') != (NEW.counter_value IS NOT NULL) THEN RAISE(ABORT,'measurement semantics mismatch') END; END;
CREATE TABLE metric_aggregates (monitor_id TEXT NOT NULL REFERENCES monitor_definitions(id) ON DELETE CASCADE, bucket_ms INTEGER NOT NULL, resolution_ms INTEGER NOT NULL CHECK(resolution_ms IN (60000,3600000)), samples INTEGER NOT NULL, minimum REAL NOT NULL, maximum REAL NOT NULL, total REAL NOT NULL, PRIMARY KEY(monitor_id,resolution_ms,bucket_ms)) STRICT;
CREATE INDEX aggregates_retention ON metric_aggregates(resolution_ms,bucket_ms);
CREATE TABLE state_transitions (id TEXT PRIMARY KEY NOT NULL, monitor_id TEXT NOT NULL REFERENCES monitor_definitions(id) ON DELETE CASCADE, previous_state TEXT NOT NULL, new_state TEXT NOT NULL, observed_at INTEGER NOT NULL, received_at INTEGER NOT NULL) STRICT;
CREATE INDEX transitions_history ON state_transitions(monitor_id,observed_at DESC);
CREATE TABLE alert_rules (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL DEFAULT 'default' REFERENCES sites(id), name TEXT NOT NULL, target_type TEXT NOT NULL, metric_name TEXT NOT NULL, condition TEXT NOT NULL CHECK(condition IN ('>','<','>=','<=','==','!=')), threshold REAL NOT NULL, severity TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), webhook_url TEXT CHECK(webhook_url IS NULL OR webhook_url='')) STRICT;
CREATE TABLE alerts (id TEXT PRIMARY KEY NOT NULL, node_id TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, rule_id TEXT REFERENCES alert_rules(id) ON DELETE SET NULL, node_name TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','acknowledged','resolved')), created_at INTEGER NOT NULL, ack_at INTEGER, ack_by TEXT) STRICT;
CREATE INDEX incidents_history ON alerts(node_id,created_at DESC);
CREATE TABLE notifications (id TEXT PRIMARY KEY NOT NULL, incident_id TEXT NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(channel IN ('webhook','email','syslog')), status TEXT NOT NULL CHECK(status IN ('pending','sent','failed')), attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, sent_at INTEGER) STRICT;
CREATE TABLE audit_logs (id TEXT PRIMARY KEY NOT NULL, user TEXT NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL, timestamp INTEGER NOT NULL) STRICT;
CREATE INDEX audit_history ON audit_logs(timestamp DESC);
CREATE TABLE discovered_devices (id TEXT PRIMARY KEY NOT NULL, site_id TEXT NOT NULL DEFAULT 'default' REFERENCES sites(id), ip TEXT NOT NULL, mac TEXT, vendor TEXT, hostname TEXT, detected_type TEXT, open_ports TEXT, status TEXT DEFAULT 'new', last_scanned INTEGER, UNIQUE(site_id,ip)) STRICT;
CREATE VIEW metric_history AS SELECT m.id,d.node_id,m.observed_at AS timestamp,CASE WHEN d.metric_name='cpu' THEN m.value END AS cpu,CASE WHEN d.metric_name='memory' THEN m.value END AS memory,CASE WHEN d.metric_name='disk' THEN m.value END AS disk,CASE WHEN d.metric_name='latency' THEN m.value END AS latency,NULL AS rx_mbps,NULL AS tx_mbps FROM measurements m JOIN monitor_definitions d ON d.id=m.monitor_id;
CREATE INDEX monitors_collector ON monitor_definitions(collector_id,site_id);
CREATE INDEX monitors_interface ON monitor_definitions(interface_id,node_id);
CREATE INDEX nodes_credentials ON nodes(credential_id,site_id);
CREATE INDEX ports_peer ON switch_ports(connected_device_id);
CREATE INDEX notifications_incident ON notifications(incident_id);
CREATE INDEX incidents_rule ON alerts(rule_id);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TRIGGER monitor_semantics_immutable BEFORE UPDATE OF units,semantics,metric_name,node_id,interface_id,collector_id ON monitor_definitions WHEN EXISTS(SELECT 1 FROM measurements WHERE monitor_id=OLD.id) OR EXISTS(SELECT 1 FROM metric_aggregates WHERE monitor_id=OLD.id) BEGIN SELECT RAISE(ABORT,'Create a new monitor identity when changing telemetry semantics'); END;
CREATE TRIGGER measurement_semantics_update BEFORE UPDATE ON measurements BEGIN SELECT RAISE(ABORT,'Measurements are immutable'); END;
CREATE TRIGGER interface_bound BEFORE INSERT ON switch_ports WHEN (SELECT count(*) FROM switch_ports WHERE node_id=NEW.node_id)>=4096 BEGIN SELECT RAISE(ABORT,'Interface cardinality limit reached'); END;
